    "theme": "data-dense",
    "audience": "researchers and policy makers",
    "tone": "analytical, publication-ready, impactful"
  },
  "goal": [
    {
      "id": "sankey-encoding-mapping",
      "insight": "Encode a three-stage Sankey diagram: 9 primary energy sources (left) → 4 transformation processes (middle) → 5 end-use sectors (right), with flow band width proportional to energy in exajoules (EJ)"
    },
    {
      "id": "waste-heat-dominance",
      "insight": "Visually highlight the waste/rejected heat flow using a distinct warm color so that its magnitude clearly stands out as larger than the combined total of all renewable energy source flows"
    },
    {
      "id": "fossil-fuel-pathway",
      "insight": "Emphasize the dominant pathways from fossil fuels (oil, coal, natural gas) through thermal power generation and refining, showing how they constitute the bulk of total energy flow"
    },
    {
      "id": "renewable-share-contrast",
      "insight": "Show the relatively thin flows from renewable sources (solar, wind, hydro, biomass, geothermal) compared to fossil fuel flows, making the scale disparity visually apparent"
    },
    {
      "id": "end-use-distribution",
      "insight": "Display how energy distributes across the five end-use sectors (transport, industry, buildings, agriculture, other), with transport and industry receiving the largest shares"
    }
  ]
}

